                    $available_currencies = $product->get_available_currencies();
                    $default_price = $product->get_default_price();
                    $prices = $product->get_prices();

                    $initial_currency = $product->get_initiate_checkout_currency();
                    $initial_quantity = max(20, min(50, intval($_GET['seats'] ?? 2)));
                    $initial_price_obj = null;

                    $initial_price_id = isset($_GET['price_id']) ? sanitize_text_field(wp_unslash($_GET['price_id'])) : '';
                    if ( $initial_price_id ) {
                        $initial_price_obj = array_reduce($prices, function($carry, $price) use ($initial_price_id) {
                            return ($price->get_id() === $initial_price_id) ? $price : $carry;
                        }, null);
                    }

                    if ( ! $initial_price_obj ) {
                        $default_price = $product->get_default_price();
                        if ( $default_price && ! is_wp_error( $default_price ) && ! $default_price->has_error() ) {
                            $initial_price_obj = $default_price;
                        }
                    }

                    $initial_display_unit = '---';
                    $initial_display_subtotal = '---';
                    $initial_display_desc = '---';
                    
                    if ( $initial_price_obj && $initial_price_obj instanceof \YTISM\Core\Price && ! $initial_price_obj->has_error() ) {
                        $calculated_amounts = $initial_price_obj->calculate_total_for_currency( $initial_quantity, $initial_currency );
                        if ( ! is_wp_error( $calculated_amounts ) ) {
                            $interal_name = $calculated_amounts['recurring_interval_i18n'] ? '<span class="ytism-price-recurring-interval">/' . esc_html( $calculated_amounts['recurring_interval_i18n'] ) . '</span>' : '';
                            
                            $initial_display_subtotal = $calculated_amounts['subtotal'] . $interal_name;
                            $initial_display_unit = $calculated_amounts['price_per_unit'] ?? '---';
                            $initial_display_desc = $calculated_amounts['price_description'] ?? '---';
                        } else {
                            \YTISM\Helpers\Functions::delog_debug( 'Application Error on initial load calculation: ' . $calculated_amounts->get_error_message() );
                        }
                    }

                    // --- End Initial Calculation ---
                    ?>
