                                                id="price-<?php echo esc_attr( $price->get_id() ); ?>"
                                                value="<?php echo esc_attr( $price->get_id() ); ?>"
                                                data-price-object="<?php echo esc_attr( wp_json_encode( $price->get_object() ) ); ?>"
